// Systemnachrichten senden (SYS 9, BA8, Stefan 20.10.2026): je übernommene Nachricht ein Eintrag. Versand nur über die fest erlaubte Zugangs-ID
// „Systemnachrichten – Versand (SMTP)“; Absender (Adresse und Name) aus den Einstellungen, Empfang nur aus der Datenbank. Termine mit .ics-Anhang.
// Passt etwas nicht, wird die Nachricht nicht gesendet, sondern mit Grund als Fehler zurückgemeldet (kein zweiter Versand).
// Plan 56c (Prüfung Fassung 1.0, S1): Installationswert statt fester ID aus der Quell-Installation; das Installationsskript ersetzt den Platzhalter
// (Beipackzettel „installationswerte“). Ohne Ersatz passt kein Zugang, es wird nichts gesendet.
const ERLAUBT = '__ALLY_ZUGANG_SYSTEMNACHRICHTEN_SMTP__';
const r = ($input.first().json || {}).r || {};
// Fehler Nr. 24 (Stefan 02.11.2026, Migration 198): ist ein vorhandenes Postfach der Absender, geht die Nachricht über dessen Workflow „MAIL Postfach Nr. n“
// (Aktion senden, wie TALENTS Mail-Entwürfe); sonst wie bisher über die Zugangsdaten für Systemnachrichten.
const PLATZ = r.art === 'platz';
const PLATZ_OK = PLATZ && /^[A-Za-z0-9]{8,40}$/.test(String(r.workflow_id || '')) && Number.isInteger(Number(r.platz)) && Number(r.platz) >= 1;
const N = Array.isArray(r.nachrichten) ? r.nachrichten : [];
if (r.aktiv !== true || !N.length) return [];
const MAIL = /^[A-Za-z0-9._%+-]{1,64}@[A-Za-z0-9-]{1,63}(\.[A-Za-z0-9-]{1,63})*\.[A-Za-z]{2,63}$/;
const NAME = /^[^<>"\\,;:()\r\n]{1,80}$/;
const s = v => String(v ?? '');
const aus = [];
for (const n of N) {
  const id = Number(n.id);
  if (!Number.isInteger(id) || id <= 0) continue;
  let fehler = '';
  if (PLATZ && !PLATZ_OK) fehler = 'Der Versand des Postfachs ist nicht eingerichtet.';
  else if (!PLATZ && s(r.credential_id) !== ERLAUBT) fehler = 'Zugangsdaten für den Versand stimmen nicht.';
  else if (!MAIL.test(s(r.von_adresse)) || !NAME.test(s(r.von_name))) fehler = 'Absender ungültig.';
  else if (!MAIL.test(s(n.an))) fehler = 'Empfangsadresse ungültig.';
  else if (!s(n.betreff) || /[\r\n]/.test(s(n.betreff))) fehler = 'Betreff ungültig.';
  else if (!s(n.text)) fehler = 'Inhalt fehlt.';
  const it = { json: { id, an: s(n.an), betreff: s(n.betreff).slice(0, 200), text: s(n.text), html: s(n.html) || s(n.text), von: '"' + s(r.von_name) + '" <' + s(r.von_adresse) + '>',
    mit_ics: false, fehler, weg: PLATZ ? 'postfach' : 'smtp' } };
  if (PLATZ) Object.assign(it.json, { aktion: 'senden', nr: Number(r.platz), workflow_id: s(r.workflow_id), anhaenge: '' });
  if (!fehler && s(n.ics).startsWith('BEGIN:VCALENDAR')) {
    const name = /^[a-z0-9_-]{1,40}\.ics$/.test(s(n.ics_name)) ? s(n.ics_name) : 'termin.ics';
    it.binary = { ics: { data: Buffer.from(s(n.ics), 'utf8').toString('base64'), mimeType: 'text/calendar', fileName: name, fileExtension: 'ics' } };
    it.json.mit_ics = true;
    if (PLATZ) it.json.anhaenge = 'ics';
  }
  aus.push(it);
}
return aus;

// Ergebnis je Nachricht (SYS 9): Kennung über die Zuordnung der Einträge aus „Nachrichten vorbereiten“; gesendet nur, wenn der Server die Adresse angenommen hat.
const v = $('Nachrichten vorbereiten').item.json;
const j = $json || {};
const t = x => String(x ?? '').replace(/\s+/g, ' ').trim().slice(0, 300);
let ok = false, meldung = '';
if (v.fehler) meldung = t(v.fehler);
else if (j.error) meldung = t((j.error && (j.error.message || j.error.description)) || j.error) || 'Versand fehlgeschlagen.';
else if (Array.isArray(j.rejected) && j.rejected.length) meldung = 'Vom Mailserver abgelehnt: ' + t(j.rejected.join(', '));
else if ((Array.isArray(j.accepted) && j.accepted.length) || j.messageId) ok = true;
else meldung = 'Keine Bestätigung vom Mailserver.';
return { json: { id: v.id, ok, meldung } };
